-- ============================================================================================================
-- 刷题种子数据：中国近现代史纲要（2025年复习题库）
-- ============================================================================================================
-- 来源：2025年中国近现代史纲要复习题库.doc（Word 转纯文本后解析生成）
-- 生成方式：脚本解析，题目按「第X章」归属，题型由答案字母个数推导（1 个=单选，≥2 个=多选）
-- 执行方式：
--   mysql -uroot -p studio_db < db/quiz-seed-history.sql
--   或在已登录的 mysql 客户端里：source db/quiz-seed-history.sql
--
-- 可重复执行：所有行使用**固定 ID**（1925000000000000000 + 序号）+ ON DUPLICATE KEY UPDATE，
-- 重跑只会把题干/选项/答案刷新成脚本里的版本，不会产生重复题目。
-- 注意：若管理员在后台「删除」了某题（逻辑删除），重跑**不会**把它复活——
--       UPDATE 分支不触碰 deleted_at，这是刻意的（尊重后台的删除决定）。
-- ============================================================================================================

SET NAMES utf8mb4;

AS new
ON DUPLICATE KEY UPDATE
    `textbook_name`  = new.`textbook_name`,
    `textbook_seq`   = new.`textbook_seq`,
    `chapter_name`   = new.`chapter_name`,
    `chapter_seq`    = new.`chapter_seq`,
    `type`           = new.`type`,
    `stem`           = new.`stem`,
    `options`        = new.`options`,
    `correct_labels` = new.`correct_labels`,
    `source`         = new.`source`,
    `question_seq`   = new.`question_seq`,
    `updated_at`     = NOW();
