(1925000000000000282,'中国近现代史纲要',10,'第六章 中华民族的抗日战争',6,0,'中国人民抗日战争胜利的纪念日是','[{"label":"A","content":"1945年8月14日"},{"label":"B","content":"1945年8月15日"},{"label":"C","content":"1945年9月2日"},{"label":"D","content":"1945年9月3日"}]','D',NULL,1,'2025年复习题库',46,0,NOW(),NOW(),0,0,0),
(1925000000000000283,'中国近现代史纲要',10,'第六章 中华民族的抗日战争',6,0,'抗日战争能够取得胜利的决定性因素是','[{"label":"A","content":"国民政府正面战场的抗战"},{"label":"B","content":"世界反法西斯力量的援助"},{"label":"C","content":"敌后战场军民的英勇抗战"},{"label":"D","content":"以爱国主义为核心的民族精神"}]','D',NULL,1,'2025年复习题库',47,0,NOW(),NOW(),0,0,0),
(1925000000000000284,'中国近现代史纲要',10,'第六章 中华民族的抗日战争',6,1,'中国人民抗日战争在世界反法西斯战争中的地位与作用表现为','[{"label":"A","content":"是世界反法西斯战争的东方主战场"},{"label":"B","content":"牵制和削弱了日本的力量，使之不敢贸然北进，又不能全力南进"},{"label":"C","content":"减轻了盟军的压力，为实施战略反攻创造了有利条件"},{"label":"D","content":"为盟国提供了大量战略物资和军事情报"}]','ABCD',NULL,1,'2025年复习题库',48,0,NOW(),NOW(),0,0,0),
(1925000000000000285,'中国近现代史纲要',10,'第六章 中华民族的抗日战争',6,1,'中国人民抗日战争的胜利，形成了伟大的抗战精神。这就是：','[{"label":"A","content":"天下兴亡、匹夫有责的爱国情怀"},{"label":"B","content":"视死如归、宁死不屈的民族气节"},{"label":"C","content":"不畏强暴、血战到底的英雄气概"},{"label":"D","content":"百折不挠、坚忍不拔的必胜信念"}]','ABCD',NULL,1,'2025年复习题库',49,0,NOW(),NOW(),0,0,0),
(1925000000000000286,'中国近现代史纲要',10,'第六章 中华民族的抗日战争',6,1,'抗日战争胜利的意义包括','[{"label":"A","content":"彻底粉碎了日本军国主义殖民奴役中国的图谋，捍卫了国家主权和领土完整"},{"label":"B","content":"开辟了中华民族复兴的光明前景"},{"label":"C","content":"促进了中华民族的大团结，形成了伟大的抗战精神"},{"label":"D","content":"对世界各国夺取反法西斯战争的胜利、维护世界和平的事业产生了巨大的影响"}]','ABCD',NULL,1,'2025年复习题库',50,0,NOW(),NOW(),0,0,0),
(1925000000000000287,'中国近现代史纲要',10,'第六章 中华民族的抗日战争',6,1,'胡锦涛同志指出"中国共产党在全民族抗战中发挥了中流砥柱的作用。"这种"中流砥柱的作用"主要表现在','[{"label":"A","content":"倡导、促成、维护抗日民族统一战线，成为凝聚全民族力量的组织者和鼓舞者"},{"label":"B","content":"在正面战场发挥了主要作用"},{"label":"C","content":"制定了正确的战略和策略"},{"label":"D","content":"中国共产党人以献身精神和模范行动，成为夺取抗战胜利的民族先锋"}]','ACD',NULL,1,'2025年复习题库',51,0,NOW(),NOW(),0,0,0),
(1925000000000000288,'中国近现代史纲要',10,'第七章 为新中国而奋斗',7,0,'抗战胜利后，蒋介石集团的既定方针是','[{"label":"A","content":"坚持独裁统治，继续走半殖民地半封建社会的老路"},{"label":"B","content":"通过政治和谈方式解决中共问题"},{"label":"C","content":"以武力消灭共产党及其领导的人民军队和解放区政权"},{"label":"D","content":"建立资产阶级共和国"}]','C',NULL,1,'2025年复习题库',1,0,NOW(),NOW(),0,0,0),
(1925000000000000289,'中国近现代史纲要',10,'第七章 为新中国而奋斗',7,1,'蒋介石在积极准备内战的同时，又表示愿意与中共进行和平谈判的目的是','[{"label":"A","content":"想通过和平方式让中共做出让步"},{"label":"B","content":"以此敷衍国内外舆论，掩盖其正在进行的内战准备"},{"label":"C","content":"诱使中共交出人民军队和解放区政权，以期不战而控制全中国"},{"label":"D","content":"如谈判不成，即放手发动内战，把战争责任转嫁给中共"}]','BCD',NULL,1,'2025年复习题库',2,0,NOW(),NOW(),0,0,0),
(1925000000000000290,'中国近现代史纲要',10,'第七章 为新中国而奋斗',7,1,'抗日战争胜利前后，美国在中国采取扶蒋反共的政策，其意图在于','[{"label":"A","content":"避免共产党完全控制中国"},{"label":"B","content":"推动建立一个统一的亲美政府"},{"label":"C","content":"扶植和发展中国民族资本，发展民主"},{"label":"D","content":"维护美国在中国的殖民主义利益"}]','ABD',NULL,1,'2025年复习题库',3,0,NOW(),NOW(),0,0,0),
(1925000000000000291,'中国近现代史纲要',10,'第七章 为新中国而奋斗',7,0,'1945年8月25日，中共中央在对时局的宣言中明确提出的口号是','[{"label":"A","content":"和平、民主、团结"},{"label":"B","content":"打倒蒋介石，解放全中国"},{"label":"C","content":"向北发展，向南防御"},{"label":"D","content":"将革命进行到底"}]','A',NULL,1,'2025年复习题库',4,0,NOW(),NOW(),0,0,0),
(1925000000000000292,'中国近现代史纲要',10,'第七章 为新中国而奋斗',7,0,'1945年8月29日，重庆《大公报》就毛泽东赴重庆谈判发表了《毛泽东先生来了!》的社评，其中写道："毛泽东先生来了，中国人听了高兴，世界人听了高兴，无疑问的大家都认为这是中国的一件大喜事。"毛泽东赴重庆谈判的目的是','[{"label":"A","content":"结束国共内战"},{"label":"B","content":"商讨联合抗日"},{"label":"C","content":"寻求外国援助"},{"label":"D","content":"争取和平民主"}]','D',NULL,1,'2025年复习题库',5,0,NOW(),NOW(),0,0,0),
(1925000000000000293,'中国近现代史纲要',10,'第七章 为新中国而奋斗',7,0,'1945年10月10日，国共两党经过谈判，签订《政府与中共代表会谈纪要》，确定','[{"label":"A","content":"建立民主联合政府"},{"label":"B","content":"和平建国的基本方针"},{"label":"C","content":"实行宪政、结束训政"},{"label":"D","content":"保护人民的民主、自由权利"}]','B',NULL,1,'2025年复习题库',6,0,NOW(),NOW(),0,0,0),
(1925000000000000294,'中国近现代史纲要',10,'第七章 为新中国而奋斗',7,1,'抗日战争结束后，中国共产党争取和平民主的努力的作用有','[{"label":"A","content":"阻止了全面内战的爆发"},{"label":"B","content":"使各界群众增强了对中国共产党的了解"},{"label":"C","content":"使各界群众懂得了什么人应当对这场战争承担责任"},{"label":"D","content":"赢得了准备自卫战争的时间"}]','BCD',NULL,1,'2025年复习题库',7,0,NOW(),NOW(),0,0,0),
(1925000000000000295,'中国近现代史纲要',10,'第七章 为新中国而奋斗',7,0,'1946年6月全面内战爆发时，国民党军队首先进攻的地区是','[{"label":"A","content":"中原解放区"},{"label":"B","content":"东北解放区"},{"label":"C","content":"山东解放区"},{"label":"D","content":"陕甘宁解放区"}]','A',NULL,1,'2025年复习题库',8,0,NOW(),NOW(),0,0,0),
