(1925000000000000379,'中国近现代史纲要',10,'第八章 中华人民共和国的成立与中国社会主义建设道路的探索',8,0,'标志着"文化大革命"在理论与实践上都破产的事件是','[{"label":"A","content":"九一三事件"},{"label":"B","content":"二月逆流"},{"label":"C","content":"炮打司令部"},{"label":"D","content":"中共九大"}]','A',NULL,1,'2025年复习题库',47,0,NOW(),NOW(),0,0,0),
(1925000000000000380,'中国近现代史纲要',10,'第八章 中华人民共和国的成立与中国社会主义建设道路的探索',8,0,'1976年"文化大革命"结束后，造成党和国家的工作在徘徊中前进局面的根源在于','[{"label":"A","content":"\\"阶级斗争为纲\\"的错误方针"},{"label":"B","content":"\\"批林批孔\\"的错误方针"},{"label":"C","content":"\\"反击右倾翻案风\\"的错误方针"},{"label":"D","content":"\\"两个凡是\\"的错误方针"}]','D',NULL,1,'2025年复习题库',48,0,NOW(),NOW(),0,0,0),
(1925000000000000381,'中国近现代史纲要',10,'第八章 中华人民共和国的成立与中国社会主义建设道路的探索',8,0,'中国自开始全面建设社会主义以来，尽管经历过严重的曲折，还是取得了巨大的成就，其中该时期最大的建设成就是','[{"label":"A","content":"国际地位得到提高与国际环境得到改善"},{"label":"B","content":"人民生活水平的提高和文化、医疗、科技事业的发展"},{"label":"C","content":"在探索中形成了建设社会主义的若干重要原则"},{"label":"D","content":"独立的、比较完整的工业体系和国民经济体系的基本建立"}]','D',NULL,1,'2025年复习题库',49,0,NOW(),NOW(),0,0,0),
(1925000000000000382,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,1,'"两个凡是"，即"凡是毛主席做出的决策，我们都坚决维护，凡是毛主席的指示，我们都始终不渝的遵循。"，这一指导思想的提出','[{"label":"A","content":"是对毛泽东思想的继承和发展"},{"label":"B","content":"挽救了党和国家的前途命运"},{"label":"C","content":"使彻底纠正\\"左\\"倾错误要求和愿望遇到严重阻碍"},{"label":"D","content":"导致党和国家的事业出现了徘徊的局面"}]','CD',NULL,1,'2025年复习题库',1,0,NOW(),NOW(),0,0,0),
(1925000000000000383,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,0,'1978年，由《实践是检验真理的唯一标准》一文引发，在全党全社会迅速展开的并成为正本清源、拨乱反正和改革开放思想先导的历史事件是','[{"label":"A","content":"\\"两个凡是\\"的提出"},{"label":"B","content":"关于真理标准问题的大讨论"},{"label":"C","content":"全国科学大会的召开"},{"label":"D","content":"揭批\\"四人帮\\"的群众运动"}]','B',NULL,1,'2025年复习题库',2,0,NOW(),NOW(),0,0,0),
(1925000000000000384,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,0,'真理问题标准大讨论的实质是','[{"label":"A","content":"冲破\\"两个凡是\\"的严重束缚"},{"label":"B","content":"坚持马列主义、毛泽东思想"},{"label":"C","content":"纠正\\"左\\"倾错误"},{"label":"D","content":"完整准确地理解毛泽东思想"}]','B',NULL,1,'2025年复习题库',3,0,NOW(),NOW(),0,0,0),
(1925000000000000385,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,0,'成为开辟中国特色社会主义新道路、开创中国特色社会主义新理论的宣言书的是','[{"label":"A","content":"《中共十一届三中全会公报》"},{"label":"B","content":"《解放思想，实事求是，团结一致向前看》"},{"label":"C","content":"《关于建国以来党的若干历史问题的决议》"},{"label":"D","content":"《实践是检验真理的唯一标准》"}]','B',NULL,1,'2025年复习题库',4,0,NOW(),NOW(),0,0,0),
(1925000000000000386,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,0,'1978年12月，党的十一届三中全会的胜利召开','[{"label":"A","content":"提出了\\"建设有中国特色社会主义\\"的重大命题"},{"label":"B","content":"把改革开放和现代化建设推向新阶段"},{"label":"C","content":"开启了改革开放和社会主义现代化建设新时期"},{"label":"D","content":"标志着党在指导思想上拨乱反正的胜利完成"}]','C',NULL,1,'2025年复习题库',5,0,NOW(),NOW(),0,0,0),
(1925000000000000387,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,1,'1978年12月，党召开十一届三中全会，实现了新中国成立以来党的历史上具有深远意义的伟大转折。党的十一届三中全会','[{"label":"A","content":"果断结束\\"以阶级斗争为纲\\""},{"label":"B","content":"实现党和国家工作中心战略转移"},{"label":"C","content":"标志着党在指导思想上的拨乱反正胜利完成"},{"label":"D","content":"开启了改革开放和社会主义现代化建设新时期"}]','ABD',NULL,1,'2025年复习题库',6,0,NOW(),NOW(),0,0,0),
(1925000000000000388,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,0,'十一届三中全会之所以成为新中国历史上具有深远意义的伟大转折，主要是因为','[{"label":"A","content":"重新确立了实事求是的指导方针"},{"label":"B","content":"停止了\\"以阶级斗争为纲\\"的错误方针"},{"label":"C","content":"作出了改革开放的伟大决策，把工作重点转移到经济建设上来"},{"label":"D","content":"重新确立马克思主义组织路线"}]','C',NULL,1,'2025年复习题库',7,0,NOW(),NOW(),0,0,0),
(1925000000000000389,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,1,'中国共产党历来高度注重总结历史经验。1981年，党的十一届六中全会通过了《关于建国以来党的若干历史问题的决议》，回顾了新中国成立以前党的历史，总结了社会主义革命和建设的历史经验','[{"label":"A","content":"对一些重大事件和重要人物作出了评价，特别是正确评价了毛泽东同志和毛泽东思想"},{"label":"B","content":"分清了是非，纠正了\\"左\\"右两方面的错误观点，统一了全党思想"},{"label":"C","content":"标志着党在指导思想上的拨乱反正胜利完成"},{"label":"D","content":"开启了改革开放和社会主义现代化建设新时期"}]','ABC',NULL,1,'2025年复习题库',8,0,NOW(),NOW(),0,0,0),
(1925000000000000390,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,0,'1979年3月，邓小平在中央理论工作务虚会上首次明确提出了必须坚持','[{"label":"A","content":"实事求是"},{"label":"B","content":"对内改革、对外开放"},{"label":"C","content":"拨乱反正"},{"label":"D","content":"四项基本原则"}]','D',NULL,1,'2025年复习题库',9,0,NOW(),NOW(),0,0,0),
(1925000000000000391,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,0,'从1979年11月起，在邓小平主持下，中共中央着手起草《关于建国以来党的若干历史问题的决议》。邓小平对《决议》的起草提出了指导原则，其中，最核心的一条是','[{"label":"A","content":"对建国 30 年来历史上的大事，要进行实事求是的分析"},{"label":"B","content":"宜粗不宜细，总结过去是为了引导大家团结一致向前看"},{"label":"C","content":"确立毛泽东同志的历史地位，坚持和发展毛泽东思想"},{"label":"D","content":"走自己的路，开辟中国特色社会主义道路"}]','C',NULL,1,'2025年复习题库',10,0,NOW(),NOW(),0,0,0),
(1925000000000000392,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,1,'《关于建国以来党的若干历史问题的决议》科学评价了毛泽东和毛泽东思想的历史地位。该决议认为毛泽东思想活的灵魂是','[{"label":"A","content":"实事求是"},{"label":"B","content":"党的建设"},{"label":"C","content":"群众路线"},{"label":"D","content":"独立自主"}]','ACD',NULL,1,'2025年复习题库',11,0,NOW(),NOW(),0,0,0),
(1925000000000000393,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,0,'中国共产党敢于正视自己的错误，并注意从自己所犯的错误中学习并汲取教训的。党和国家在指导思想上拨乱反正胜利完成标志是','[{"label":"A","content":"党的十一届三中全会的召开"},{"label":"B","content":"《解放思想，实事求是，团结一致向前看》的发表"},{"label":"C","content":"真理问题标准大讨论"},{"label":"D","content":"《关于建国以来党的若干历史问题的决议》的通过"}]','D',NULL,1,'2025年复习题库',12,0,NOW(),NOW(),0,0,0),
(1925000000000000394,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,0,'《关于建国以来党的若干历史问题的决议》对于新时期我国社会主义矛盾的提法:社会主义改造基本完成以后，我国所要解决的主要矛盾是','[{"label":"A","content":"人民日益增长的物质文化需要同落后的社会生产之间的矛盾"},{"label":"B","content":"人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾"},{"label":"C","content":"人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾"},{"label":"D","content":"人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾"}]','A',NULL,1,'2025年复习题库',13,0,NOW(),NOW(),0,0,0),
(1925000000000000395,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,0,'1981年，党的十一届六中全会通过了《关于建国以来党的若干历史问题的决议》，具有深远历史意义。《决议》的通过标志着','[{"label":"A","content":"党重新确立了马克思主义的思想路线、政治路线、组织路线"},{"label":"B","content":"党在指导思想上拨乱反正的胜利完成"},{"label":"C","content":"新中国成立以来党的历史上具有深远意义的伟大转折的实现"},{"label":"D","content":"我国改革开放和社会主义现代化建设新时期的开启"}]','B',NULL,1,'2025年复习题库',14,0,NOW(),NOW(),0,0,0),
(1925000000000000396,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,0,'1977年至1978年，我国出现国民经济比例失调的情况，1979年4月召开的中共中央经济工作会议，对国民经济实行的方针是','[{"label":"A","content":"\\"调整、改革、充实、提高\\""},{"label":"B","content":"\\"调整、改革、整顿、提高\\""},{"label":"C","content":"\\"调整、巩固、整顿、提高\\""},{"label":"D","content":"\\"调整、巩固、充实、提高\\""}]','B',NULL,1,'2025年复习题库',15,0,NOW(),NOW(),0,0,0),
(1925000000000000397,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,1,'1979年，针对当时存在的是否还要坚持毛泽东思想的问题，邓小平指出："有些同志说，我们只拥护''正确的毛泽东思想''，而不是拥护错误的毛泽东思想。这种说法也是有错误的。""这种说法"之所以错误，是因为','[{"label":"A","content":"没有把毛泽东与党的其他领导人对毛泽东思想的贡献区分开"},{"label":"B","content":"没有把毛泽东思想与有中国特色社会主义理论区分开"},{"label":"C","content":"没有把毛泽东思想与毛泽东的思想区分开"},{"label":"D","content":"没有把毛泽东晚年的错误与毛泽东思想的科学体系区分开"}]','CD',NULL,1,'2025年复习题库',16,0,NOW(),NOW(),0,0,0),
(1925000000000000398,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,1,'1980年8月，邓小平会见意大利记者奥琳埃娜·法拉奇。法拉奇问："天安门上的毛主席像，是否要永远保留下去？"邓小平回答说："永远要保留下去......"。毛主席像要在天安门上永远保留下去的主要原因有','[{"label":"A","content":"毛泽东为新中国的缔造做出了不可磨灭的贡献"},{"label":"B","content":"毛泽东思想是中国革命和建设的正确理论原则和经验总结"},{"label":"C","content":"毛泽东晚年犯了严重错误"},{"label":"D","content":"毛泽东的思想就是毛泽东思想"}]','AB',NULL,1,'2025年复习题库',17,0,NOW(),NOW(),0,0,0),
(1925000000000000399,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,1,'深圳、珠海等经济特区的创办','[{"label":"A","content":"是党中央坚强领导、悉心指导的结果"},{"label":"B","content":"是广大建设者开拓进取、奋勇拼搏的结果"},{"label":"C","content":"是外商投资设厂的结果"},{"label":"D","content":"是全国人民和四面八方倾力支持、广泛参与的结果"}]','ABD',NULL,1,'2025年复习题库',18,0,NOW(),NOW(),0,0,0),
(1925000000000000400,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,1,'特区精神包括','[{"label":"A","content":"敢闯敢试"},{"label":"B","content":"敢为人先"},{"label":"C","content":"埋头苦干"},{"label":"D","content":"立党为公"}]','ABC',NULL,1,'2025年复习题库',19,0,NOW(),NOW(),0,0,0),
(1925000000000000401,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,0,'"把马克思主义的普遍真理同我国的具体实际结合起来，走自己的道路，建设有中国特色的社会主义"，这是邓小平在党的代表大会上的开幕词中提出的，这次党的代表大会是','[{"label":"A","content":"中共十二大"},{"label":"B","content":"中共十三大"},{"label":"C","content":"中共十四大"},{"label":"D","content":"中共十五大"}]','A',NULL,1,'2025年复习题库',20,0,NOW(),NOW(),0,0,0),
(1925000000000000402,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,0,'中共十三大明确概括了','[{"label":"A","content":"全面建设小康社会的奋斗目标"},{"label":"B","content":"党在社会主义初级阶段的基本纲领"},{"label":"C","content":"社会主义市场经济体制的改革目标"},{"label":"D","content":"社会主义初级阶段理论和党的基本路线"}]','D',NULL,1,'2025年复习题库',21,0,NOW(),NOW(),0,0,0),
(1925000000000000403,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,1,'党在社会主义初级阶段的基本路线的主要内容是','[{"label":"A","content":"坚持\\"三步走\\"发展战略"},{"label":"B","content":"以经济建设为中心"},{"label":"C","content":"坚持四项基本原则"},{"label":"D","content":"坚持改革开放"}]','BCD',NULL,1,'2025年复习题库',22,0,NOW(),NOW(),0,0,0),
(1925000000000000404,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,1,'1992年，邓小平在视察南方的谈话中阐述了一系列重要思想，其中最主要的有','[{"label":"A","content":"关于社会主义初级阶段基本经济制度的思想"},{"label":"B","content":"关于发展才是硬道理的思想"},{"label":"C","content":"关于社会主义本质的思想"},{"label":"D","content":"关于计划和市场都是经济手段的思想"}]','BCD',NULL,1,'2025年复习题库',23,0,NOW(),NOW(),0,0,0),
(1925000000000000405,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,1,'1992年1月18日至2月21日，邓小平先后到武昌、深圳、珠海、上海等地视察，发表了一系列重要谈话，即南方谈话。邓小平的南方谈话','[{"label":"A","content":"从理论上深刻回答了长期困扰和束缚人们思想的许多重大问题"},{"label":"B","content":"是把改革开放和现代化建设推向新阶段的又一个解放思想、实事求是的宣言书"},{"label":"C","content":"对之后召开的党的十四大具有十分重要的指导作用"},{"label":"D","content":"开启了我国改革开放和社会主义现代化建设新时期"}]','ABC',NULL,1,'2025年复习题库',24,0,NOW(),NOW(),0,0,0),
(1925000000000000406,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,0,'明确提出我国经济体制改革的目标是建立社会主义市场经济体制的会议是','[{"label":"A","content":"中共十三大"},{"label":"B","content":"中共十四大"},{"label":"C","content":"中共十五大"},{"label":"D","content":"中共十六大"}]','B',NULL,1,'2025年复习题库',25,0,NOW(),NOW(),0,0,0),
(1925000000000000407,'中国近现代史纲要',10,'第九章 改革开放与中国特色社会主义的开创与发展',9,1,'1992年，我国改革开放和现代化事业进入从计划经济体制向社会主义市场经济体制转变的新阶段，由此打开了中国经济、政治、文化发展的崭新局面，其标志是','[{"label":"A","content":"邓小平南方讲话"},{"label":"B","content":"党的十四大的召开"},{"label":"C","content":"党的十五大召开"},{"label":"D","content":"党的十六大召开"}]','AB',NULL,1,'2025年复习题库',26,0,NOW(),NOW(),0,0,0),
