(1925000000000000436,'中国近现代史纲要',10,'第十章 中国特色社会主义进入新时代',10,1,'2021年是中国共产党成立100周年，在全党开展党史学习教育是','[{"label":"A","content":"牢记初心使命、推进中华民族伟大复兴历史伟业的必然要求"},{"label":"B","content":"坚定信仰信念、在新时代坚持和发展中国特色社会主义的必然要求"},{"label":"C","content":"推进党的自我革命的必然要求"},{"label":"D","content":"永葆党的生机活力的必然要求"}]','ABCD',NULL,1,'2025年复习题库',20,0,NOW(),NOW(),0,0,0),
