(1925000000000000439,'中国近现代史纲要',10,'第十章 中国特色社会主义进入新时代',10,1,'在建党百年之际，党中央召开十九届六中全会，全面总结党的百年奋斗重大成就和历史经验，是郑重的历史性、战略性决策，体现了我们党重视和善于运用历史规律的高度政治自觉，体现了我们党牢记初心使命、继往开来的自信和担当。总结党的百年奋斗重大成就和历史经验','[{"label":"A","content":"是开启全面建设社会主义现代化国家新征程、在新时代坚持和发展中国特色社会主义的需要"},{"label":"B","content":"是增强\\"四个意识\\"，坚定\\"四个自信\\"，做到\\"两个维护\\"，确保全党步调一致向前进的需要"},{"label":"C","content":"是推进党的自我革命、提高全党斗争本领和应对风险挑战能力、永葆党的生机活力、团结带领全国各族人民 为实现中华民族伟大复兴的中国梦而继续奋斗的需要"},{"label":"D","content":"对推动全党进一步统一思想、统一意志、统一行动，团结带领全国各族人民夺取新时代中国特色社会主义新的伟大胜利，具有重大现实意义和深远历史意义"}]','ABCD',NULL,1,'2025年复习题库',23,0,NOW(),NOW(),0,0,0),
(1925000000000000440,'中国近现代史纲要',10,'第十章 中国特色社会主义进入新时代',10,0,'在党成立100周年的重要历史时刻，，2021年11月，党的十九届六中全会召开，大会最重要的成果是','[{"label":"A","content":"审议通过了《中共中央关于党的百年奋斗重大成就和历史经验的决议》"},{"label":"B","content":"充分肯定了党的十九届五中全会以来中央政治局的工作"},{"label":"C","content":"审议通过了《关于召开党的第二十次全国代表大会的决议》"},{"label":"D","content":"进一步概括习近平新时代中国特色社会主义思想的核心内容"}]','A',NULL,1,'2025年复习题库',24,0,NOW(),NOW(),0,0,0),
(1925000000000000441,'中国近现代史纲要',10,'第十章 中国特色社会主义进入新时代',10,1,'党的十九届六中全会审议通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》，在全面回顾总结党的百年奋斗历程和重大成就基础上，以更宏阔的视角，总结党的百年奋斗的历史意义，指出党的百年奋斗','[{"label":"A","content":"从根本上改变了中国人民的前途命运"},{"label":"B","content":"开辟了实现中华民族伟大复兴的正确道路"},{"label":"C","content":"展示了马克思主义的强大生命力"},{"label":"D","content":"深刻影响了世界历史进程、锻造了走在时代前列的中国共产党"}]','ABCD',NULL,1,'2025年复习题库',25,0,NOW(),NOW(),0,0,0),
(1925000000000000442,'中国近现代史纲要',10,'第十章 中国特色社会主义进入新时代',10,1,'《中共中央关于党的百年奋斗重大成就和历史经验的决议》总结了中国共产党百年奋斗的十条历史经验，这十条历史经验是系统完整、相互贯通的有机整体，揭示了','[{"label":"A","content":"党和人民事业不断成功的根本保证"},{"label":"B","content":"党始终立于不败之地的力量源泉"},{"label":"C","content":"党始终掌握历史主动的根本原因"},{"label":"D","content":"党永葆先进性和纯洁性、始终走在时代前列的根本途径"}]','ABCD',NULL,1,'2025年复习题库',26,0,NOW(),NOW(),0,0,0),
(1925000000000000443,'中国近现代史纲要',10,'第十章 中国特色社会主义进入新时代',10,1,'2021年11月，党的十九届六中全会审议通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》指出习近平新时代中国特色社会主义思想','[{"label":"A","content":"是当代中国马克思主义"},{"label":"B","content":"是21世纪马克思主义"},{"label":"C","content":"是中华文化和中国精神的时代精华"},{"label":"D","content":"实现了马克思主义中国化新的飞跃"}]','ABCD',NULL,1,'2025年复习题库',27,0,NOW(),NOW(),0,0,0),
(1925000000000000444,'中国近现代史纲要',10,'第十章 中国特色社会主义进入新时代',10,0,'为实现中华民族伟大复兴提供了更为完善的制度保证、更为坚实的物质基础、更为主动的精神力量的是','[{"label":"A","content":"新民主主义革命的伟大成就"},{"label":"B","content":"社会主义革命和建设的伟大成就"},{"label":"C","content":"改革开放和社会主义现代化建设的伟大成就"},{"label":"D","content":"新时代中国特色社会主义的伟大成就"}]','D',NULL,1,'2025年复习题库',28,0,NOW(),NOW(),0,0,0),
(1925000000000000445,'中国近现代史纲要',10,'第十章 中国特色社会主义进入新时代',10,1,'党的十八大以来，中国特色社会主义进入新时代。党面临的主要任务是','[{"label":"A","content":"实现第一个百年奋斗目标"},{"label":"B","content":"开启实现第二个百年奋斗目标新征程"},{"label":"C","content":"朝着实现中华民族伟大复兴的宏伟目标继续前进"},{"label":"D","content":"为实现中华民族伟大复兴提供充满新的活力的体制保证和快速发展的物质条件"}]','ABC',NULL,1,'2025年复习题库',29,0,NOW(),NOW(),0,0,0),
(1925000000000000446,'中国近现代史纲要',10,'第十章 中国特色社会主义进入新时代',10,0,'经过不懈努力，党找到的跳出治乱兴衰历史周期率的第二个答案是','[{"label":"A","content":"人民监督政府"},{"label":"B","content":"自我革命"},{"label":"C","content":"党要管党"},{"label":"D","content":"从严治党"}]','B',NULL,1,'2025年复习题库',30,0,NOW(),NOW(),0,0,0),
(1925000000000000447,'中国近现代史纲要',10,'第十章 中国特色社会主义进入新时代',10,0,'党的二十大报告指出，新时代新征程中国共产党的使命任务是','[{"label":"A","content":"以伟大自我革命引领伟大社会革命"},{"label":"B","content":"以中国式现代化推进中华民族伟大复兴"},{"label":"C","content":"以团结奋斗创造历史伟业"},{"label":"D","content":"以新发展理念引领我国发展壮大"}]','B',NULL,1,'2025年复习题库',31,0,NOW(),NOW(),0,0,0)
